// TestMain は、利用者の git の設定 (グローバル・システム) がテストの結果を変えないように、
// 環境変数 HOME を一時ディレクトリに替え、システムの設定を読ませない。GIT_ で始まる環境変数を先に
// 取り除くのは、環境変数 GIT_DIR などが設定されたまま実行すると、テストの git が一時ディレクトリではなく
// その変数が指すリポジトリにコミットやブランチを作るため。
func TestMain(m *testing.M) {
	for _, kv := range os.Environ() {
		if k, _, _ := strings.Cut(kv, "="); strings.HasPrefix(k, "GIT_") {
			os.Unsetenv(k)
		}
	}
	home, err := os.MkdirTemp("", "lineorigin-home")
	if err != nil {
		panic(err)
	}
	for k, v := range map[string]string{
		"HOME":                home,
		"XDG_CONFIG_HOME":     home,
		"GIT_CONFIG_NOSYSTEM": "1",
		"GIT_AUTHOR_NAME":     "t",
		"GIT_AUTHOR_EMAIL":    "t@example.com",
		"GIT_COMMITTER_NAME":  "t",
		"GIT_COMMITTER_EMAIL": "t@example.com",
	} {
		os.Setenv(k, v)
	}
	// 環境変数 GIT_CONFIG_NOSYSTEM は、道具の関数 gitEnv が取り除くので、取り除いた後に足すスライス (変数 extraGitEnv) にも入れる
	extraGitEnv = []string{"GIT_CONFIG_NOSYSTEM=1"}
	code := m.Run()
	os.RemoveAll(home)
	os.Exit(code)
}

// repo は、テストごとに作る使い捨てのリポジトリ。
type repo struct {
	t   *testing.T
	dir string
}

func newRepo(t *testing.T) *repo {
	t.Helper()
	r := &repo{t: t, dir: t.TempDir()}
	r.git("init", "-q", "-b", "main")
	return r
}

// 常駐のプロセス git fsmonitor--daemon が .git の下にファイルを作って、道具が終了した後も残る。
func (g gitRunner) runIn(stdin io.Reader, args ...string) (string, int, error) {
	ctx, cancel := context.WithTimeout(context.Background(), gitTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", append([]string{"-C", g.root, "-c", "core.quotePath=false", "-c", "core.fsmonitor=false"}, args...)...)
	cmd.WaitDelay = time.Second // 期限で停止させた git の子のプロセスが出力を開いたままでも、待機し続けない
// gitEnv は git に渡す環境を作る。利用者の環境の GIT_ で始まる変数は、リポジトリの場所を替える
// (GIT_DIR・GIT_WORK_TREE・GIT_INDEX_FILE など)、設定を注入する (GIT_CONFIG_PARAMETERS・
// GIT_CONFIG_COUNT など)、パスの読み方を替える (GIT_GLOB_PATHSPECS など) ので、-root と違う
// リポジトリや設定を読ませないよう、すべて取り除いてから道具が要るものだけを足す。
func gitEnv() []string {
	var env []string
	for _, kv := range os.Environ() {
		if !strings.HasPrefix(kv, "GIT_") {
			env = append(env, kv)
		}
	}
	env = append(env,
		// git の文言 (not a git repository など) を、利用者の言語の設定によらず英語にして比べられるようにする
		"LC_ALL=C",
		// パスを pathspec (パターンや先頭の : で始まる指定) として解釈させない
		"GIT_LITERAL_PATHSPECS=1",
		// コマンド git replace の置き換えを見ない。見ると、blame が置き換えた後の履歴で、行を最後に変えたコミットを求める
		"GIT_NO_REPLACE_OBJECTS=1",
		// 部分クローンで手元に無いオブジェクトを、ネットワークから取得してリポジトリに書き込まない (git 2.44 以降)。
		// 取得できないと git は失敗し、道具は run-error になる
		"GIT_NO_LAZY_FETCH=1",
		// 認証などで利用者の入力待ちにならない
		"GIT_TERMINAL_PROMPT=0",
	)
	return append(env, extraGitEnv...)
