func TestRecordPatch(t *testing.T) {
	rec, err := parseRecord([]byte(testRecord))
	if err != nil {
		t.Fatal(err)
	}
	p, err := rec.patch(marker{kind: "patch", run: 1, problem: "P1", option: "A"})
